  'בראשית':1,'שמות':2,'ויקרא':3,'במדבר':4,'דברים':5,
  'יהושע':6,'שופטים':7,'רות':8,
  'שמואל א':9,'א שמואל':9,'שמואל ב':10,'ב שמואל':10,
