                    const matchingSets = activeVerseSets.filter(s =>
                      s && s.title && (
                        s.title.toLowerCase().includes(query) ||
                        (s.description && s.description.replace(/<[^>]+>/g, '').toLowerCase().includes(query)) ||
                        (s.authorName && s.authorName.toLowerCase().includes(query))
                      )
                    );
